INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Beta-2 Agonists','easy','mcq','Which of the following is a short-acting beta-2 agonist (SABA) used as first-line rescue therapy in acute asthma?','["A. Albuterol", "B. Indacaterol", "C. Salmeterol", "D. Formoterol"]','A','Albuterol (salbutamol) is a direct-acting beta-2-selective agonist with a rapid onset of 5-30 minutes, providing bronchodilation for 4-6 hours. It is the first-line rescue inhaler for acute bronchospasm. Salmeterol and formoterol are LABAs; indacaterol is an ultra-LABA used in COPD.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Beta-2 Agonists','easy','mcq','What is the primary mechanism of action of beta-2 adrenergic agonists in the treatment of asthma?','["A. Blockade of muscarinic receptors on airway smooth muscle", "B. Direct relaxation of airway smooth muscle via beta-2 receptor stimulation", "C. Inhibition of 5-lipoxygenase pathway", "D. Inhibition of phospholipase A2"]','B','Beta-2 agonists activate beta-2 adrenergic receptors on airway smooth muscle, increasing intracellular cAMP via adenylyl cyclase, which leads to smooth muscle relaxation and bronchodilation. They have no anti-inflammatory effects.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Beta-2 Agonists','easy','mcq','Which statement about SABAs is correct?','["A. They should be used as daily scheduled maintenance therapy in persistent asthma", "B. They have potent anti-inflammatory properties", "C. Monotherapy with a SABA may be appropriate for mild intermittent asthma", "D. They must always be combined with a LABA"]','C','SABAs (e.g., albuterol) are appropriate as monotherapy for mild intermittent asthma or exercise-induced bronchospasm. They should NOT be used as daily controllers in persistent asthma because they have no anti-inflammatory effects. LABA monotherapy (not SABA) is contraindicated.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Beta-2 Agonists','medium','mcq','A 28-year-old woman with moderate persistent asthma is well-controlled on inhaled fluticasone. She requests additional long-term bronchodilation. Which is the most appropriate LABA to add?','["A. Tiotropium", "B. Theophylline", "C. Ipratropium", "D. Salmeterol"]','D','Salmeterol is a LABA that provides bronchodilation for at least 12 hours and is indicated as adjunctive therapy with ICS for moderate-to-severe persistent asthma. LABAs must not be used as monotherapy; they must be combined with an ICS. Ipratropium and tiotropium are anticholinergics; theophylline has a narrow therapeutic index.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Beta-2 Agonists','medium','mcq','Which adverse effect is most directly caused by systemic absorption of inhaled beta-2 agonists?','["A. Hypokalemia", "B. Adrenal suppression", "C. Hepatotoxicity", "D. Oropharyngeal candidiasis"]','A','Beta-2 receptor stimulation causes cellular uptake of potassium, leading to hypokalemia. Other adverse effects include tachycardia, hyperglycemia, hypomagnesemia, and skeletal muscle tremors. Oropharyngeal candidiasis and adrenal suppression are ICS side effects.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Beta-2 Agonists','medium','mcq','Formoterol differs from salmeterol in which way?','["A. Formoterol is a short-acting agent; salmeterol is long-acting", "B. Formoterol has a faster onset and can be used for acute symptom relief in ICS/formoterol combinations", "C. Formoterol acts on beta-1 receptors, while salmeterol acts on beta-2 receptors", "D. Formoterol is only available as an oral preparation"]','B','Both salmeterol and formoterol are LABAs providing 12+ hours of bronchodilation. However, formoterol has a faster onset of action, and adults with moderate persistent asthma can use ICS/formoterol combinations for both maintenance and acute symptom relief. Salmeterol is used only on a scheduled basis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Beta-2 Agonists','medium','mcq','A 45-year-old man with COPD is started on a once-daily LABA. Which drug is most consistent with this prescription?','["A. Albuterol", "B. Levalbuterol", "C. Indacaterol", "D. Arformoterol"]','C','Indacaterol is an ultra-long-acting beta-2 agonist (LABA) approved for once-daily dosing in COPD. Albuterol and levalbuterol are SABAs. Arformoterol is administered twice daily.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Beta-2 Agonists','medium','mcq','Why is LABA monotherapy contraindicated in asthma?','["A. LABAs are nephrotoxic when administered without ICS", "B. LABAs cause severe hypertension as monotherapy", "C. LABAs cause bronchospasm when used alone", "D. LABAs without ICS are associated with increased risk of asthma-related death"]','D','Post-marketing surveillance revealed an increased risk of severe asthma-related events and death with LABA monotherapy. LABAs lack anti-inflammatory effects, so unopposed bronchodilation may mask worsening inflammation. Guidelines require LABAs to be co-administered with an ICS in asthma.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Beta-2 Agonists','hard','mcq','A patient with asthma presents with tremor, palpitations, and serum potassium of 2.9 mEq/L after excessive salbutamol nebuliser use. Which mechanism best explains the hypokalemia?','["A. Salbutamol activates beta-2 receptors on skeletal muscle, driving potassium into cells via Na+/K+-ATPase", "B. Salbutamol inhibits aldosterone secretion", "C. Salbutamol activates alpha-1 receptors, causing renal potassium wasting", "D. Salbutamol inhibits carbonic anhydrase in the renal tubule"]','A','Beta-2 agonists stimulate Na+/K+-ATPase on skeletal muscle cells, driving potassium intracellularly and lowering serum potassium. This is a dose-dependent pharmacological effect more pronounced with nebulised or IV routes than with inhaled therapy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Beta-2 Agonists','hard','mcq','A clinician prescribes levalbuterol instead of albuterol. What is the pharmacological rationale?','["A. Levalbuterol has a longer duration of action than albuterol", "B. Levalbuterol is the R-enantiomer of albuterol and is thought to have fewer cardiovascular side effects", "C. Levalbuterol is a prodrug that is activated in the lung to albuterol", "D. Levalbuterol acts on both beta-1 and beta-2 receptors"]','B','Albuterol is a racemic mixture of R- and S-enantiomers. Levalbuterol contains only the R-enantiomer (levo-albuterol), which is the pharmacologically active component responsible for bronchodilation. The S-enantiomer may contribute to adverse effects. Levalbuterol has the same duration of action as albuterol (4-6 hours).','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Anticholinergics','easy','mcq','What is the primary mechanism of action of inhaled anticholinergic agents in COPD?','["A. Inhibition of phosphodiesterase-4, increasing intracellular cAMP", "B. Stimulation of beta-2 adrenergic receptors on bronchial smooth muscle", "C. Blockade of muscarinic receptors, reducing vagally mediated bronchoconstriction and mucus secretion", "D. Inhibition of 5-lipoxygenase, reducing leukotriene production"]','C','Anticholinergics (muscarinic antagonists) block M3 muscarinic receptors on airway smooth muscle and mucus glands, reducing vagally mediated bronchoconstriction and secretions. They are foundational bronchodilators in COPD.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Anticholinergics','easy','mcq','Which anticholinergic drug is preferred for once-daily maintenance bronchodilation in COPD?','["A. Atropine", "B. Aclidinium", "C. Ipratropium", "D. Tiotropium"]','D','Tiotropium is a long-acting muscarinic antagonist (LAMA) dosed once daily. It is preferred over short-acting ipratropium for maintenance therapy in stable COPD. Ipratropium requires dosing 3-4 times daily. Atropine is not used as inhaled bronchodilator due to systemic side effects.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Anticholinergics','easy','mcq','Which adverse effect is most commonly associated with inhaled ipratropium?','["A. Dry mouth and bitter taste", "B. Oropharyngeal candidiasis", "C. Hypokalemia", "D. Tachycardia and palpitations"]','A','Inhaled ipratropium''''s most common adverse effects are dry mouth (xerostomia) and bitter taste, due to local anticholinergic effects on salivary glands. Because it is a quaternary ammonium compound, systemic absorption is minimal, making systemic side effects uncommon.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Anticholinergics','medium','mcq','A 65-year-old man with COPD has an acute exacerbation in the emergency department. He is already on nebulised salbutamol. Which anticholinergic agent is most appropriate to add?','["A. Tiotropium dry powder inhaler", "B. Ipratropium nebuliser solution", "C. Oral oxybutynin", "D. Oral glycopyrrolate"]','B','Ipratropium nebuliser solution is the appropriate short-acting anticholinergic to add alongside a SABA (salbutamol) in the acute management of COPD and asthma exacerbations. Tiotropium is for chronic maintenance, not acute exacerbations.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Anticholinergics','medium','mcq','Why is ipratropium generally NOT recommended as first-line therapy for acute asthma outside the emergency setting?','["A. It suppresses the cough reflex, masking the severity of the asthma attack", "B. It causes paradoxical bronchospasm in all asthmatic patients", "C. Its onset of action is much slower than inhaled SABAs, making it less useful for quick relief", "D. It has been associated with fatal cardiac arrhythmias in asthmatic patients"]','C','Ipratropium''''s onset of action is slower (15-30 minutes) compared to SABAs (5-15 minutes). In asthma, rapid bronchodilation is critical; therefore, SABAs are first-line. Ipratropium may be useful as an add-on in the emergency department or in patients who cannot tolerate SABAs.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Anticholinergics','medium','mcq','Tiotropium belongs to which pharmacological class?','["A. Long-acting beta-2 agonist (LABA)", "B. Phosphodiesterase-4 inhibitor", "C. Short-acting muscarinic antagonist (SAMA)", "D. Long-acting muscarinic antagonist (LAMA)"]','D','Tiotropium is a LAMA (long-acting muscarinic antagonist). It blocks M1, M2, and M3 receptors, with prolonged dissociation from M3 receptors providing 24-hour bronchodilation suitable for once-daily dosing. It is a cornerstone of maintenance therapy in stable COPD.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Anticholinergics','medium','mcq','In which clinical scenario is tiotropium indicated as add-on treatment for asthma?','["A. Adult patients with severe asthma and history of frequent exacerbations uncontrolled by ICS/LABA", "B. Children under 5 years with moderate persistent asthma", "C. Acute asthma exacerbation in the emergency department", "D. Mild intermittent asthma not controlled by SABA alone"]','A','Tiotropium can be used as add-on therapy in adult patients with severe asthma who have a history of exacerbations and remain uncontrolled on ICS plus LABA therapy. It is not first-line for mild asthma or in young children, and it is not indicated for acute attacks.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Anticholinergics','medium','mcq','How does aclidinium compare to ipratropium?','["A. Aclidinium is short-acting; ipratropium is long-acting", "B. Aclidinium is a LAMA with longer duration administered twice daily; ipratropium is a SAMA", "C. Aclidinium acts on beta-2 receptors; ipratropium acts on muscarinic receptors", "D. Aclidinium is only available intravenously; ipratropium is inhaled"]','B','Aclidinium is a long-acting muscarinic antagonist (LAMA) approved for twice-daily dosing in COPD. Ipratropium is a short-acting muscarinic antagonist (SAMA) requiring 3-4 times daily dosing. Both are quaternary ammonium compounds with minimal systemic absorption.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Anticholinergics','hard','mcq','A patient with COPD on tiotropium develops acute urinary retention. Which pharmacological property best explains why systemic effects occur despite minimal absorption?','["A. Tiotropium is selective for M2 receptors, which are not found in the bladder", "B. Tiotropium is a partial agonist at muscarinic receptors", "C. Tiotropium is a quaternary ammonium compound; small amounts absorbed from the lung can produce systemic anticholinergic effects in susceptible patients", "D. Tiotropium is rapidly hydrolysed in the blood"]','C','Tiotropium, like ipratropium, is a quaternary ammonium compound with very low GI systemic absorption. However, a fraction of inhaled drug is absorbed via the respiratory mucosa, and this can produce systemic anticholinergic effects in susceptible patients, including urinary retention in men with BPH.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Anticholinergics','hard','mcq','Per Ghana STG 2017, what is the recommended dose of nebulised ipratropium bromide for adults in acute severe asthma?','["A. 1 mg every 2 hours", "B. 18 micrograms (2 puffs) once daily", "C. 250 micrograms once only", "D. 500 micrograms every 4-6 hours"]','D','According to Ghana STG 2017, for acute moderate/severe asthma exacerbations in adults, ipratropium bromide is given by nebulisation at 500 micrograms every 4-6 hours, alongside nebulised salbutamol and systemic corticosteroids. The 18 micrograms once-daily dosing describes tiotropium.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Inhaled Corticosteroids','easy','mcq','Which drug class is the drug of choice for long-term control in patients with persistent asthma?','["A. Inhaled corticosteroids", "B. Oral theophylline", "C. Inhaled ipratropium", "D. Inhaled short-acting beta-2 agonists"]','A','ICS are the drugs of choice for long-term control in persistent asthma. They inhibit airway inflammation by blocking phospholipase A2 and the inflammatory cascade. They must be used regularly to be effective. SABAs provide only quick relief, and theophylline has a narrow therapeutic index.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Inhaled Corticosteroids','easy','mcq','A patient using inhaled beclomethasone develops white plaques in the mouth. What is the most likely diagnosis and recommended prevention?','["A. Herpes simplex labialis; prescribe aciclovir", "B. Oropharyngeal candidiasis; instruct patient to rinse mouth with water after each inhaler use", "C. Angular cheilitis due to vitamin B12 deficiency", "D. Oral leukoplakia; refer for biopsy"]','B','ICS deposition on oral and laryngeal mucosa suppresses local immunity, promoting Candida albicans overgrowth (oral thrush). Prevention involves rinsing the mouth (swish-and-spit) after every inhaler use, and using a spacer device to reduce oropharyngeal deposition.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Inhaled Corticosteroids','easy','mcq','Which ICS agent is listed in Ghana STG 2017 for chronic asthma maintenance in adults?','["A. Hydrocortisone inhaled twice daily", "B. Triamcinolone inhaled", "C. Fluticasone inhaled MDI 125-250 micrograms twice daily", "D. Dexamethasone inhaled once daily"]','C','Ghana STG 2017 recommends fluticasone inhaled MDI at 125-250 micrograms (2 puffs 12 hourly) for adults with chronic asthma maintenance. Beclomethasone and budesonide/formoterol combinations are also listed. Dexamethasone and hydrocortisone are not available as inhaled formulations.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Inhaled Corticosteroids','medium','mcq','What percentage of an ICS dose typically reaches the airways when administered via MDI without a spacer?','["A. less than 5%", "B. 60-70%", "C. 40-50%", "D. 10-20%"]','D','Only about 10-20% of an inhaled corticosteroid dose reaches the airways. The remaining 80-90% is deposited in the mouth and pharynx or swallowed. Use of a spacer device significantly improves pulmonary drug deposition by reducing particle velocity and oropharyngeal impaction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Inhaled Corticosteroids','medium','mcq','A patient with status asthmaticus requires systemic corticosteroids. Which is the most appropriate choice?','["A. IV methylprednisolone or oral prednisone", "B. Oral montelukast", "C. IM betamethasone single dose", "D. Inhaled budesonide high-dose twice daily"]','A','Status asthmaticus requires systemic corticosteroids — IV methylprednisolone or oral prednisone — to rapidly reduce airway inflammation. ICS alone are not adequate for acute severe attacks. Montelukast has no role in acute bronchospasm.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Inhaled Corticosteroids','medium','mcq','How do inhaled corticosteroids reduce airway inflammation in asthma?','["A. They stimulate beta-2 receptors and cause smooth muscle relaxation", "B. They inhibit phospholipase A2, reducing arachidonic acid release and the downstream inflammatory cascade", "C. They block cysteinyl leukotriene receptors", "D. They stabilise mast cells, preventing degranulation"]','B','ICS inhibit phospholipase A2, preventing arachidonic acid release and subsequently reducing prostaglandin and leukotriene production. They also decrease the inflammatory cascade, reverse mucosal edema, and reduce capillary permeability.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Inhaled Corticosteroids','medium','mcq','Why is a spacer device recommended for use with an MDI corticosteroid inhaler?','["A. It prevents drug interaction between the propellant and the corticosteroid molecule", "B. It increases aerosol particle speed to maximise lung deposition", "C. It filters out large drug particles, reducing oropharyngeal deposition while improving lung delivery", "D. It converts a pressurised MDI into a dry powder inhaler"]','C','A spacer (large-volume chamber) slows aerosol velocity, allowing large particles to deposit in the spacer rather than the oropharynx. Smaller particles travel more effectively to the lungs. This reduces oropharyngeal candidiasis risk and systemic absorption while improving the fraction reaching the airways.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Inhaled Corticosteroids','medium','mcq','A patient with COPD has FEV1 less than 60% and continues exacerbations despite LABA therapy. What is the appropriate role of ICS addition?','["A. ICS should replace the LABA in patients with severe COPD", "B. ICS are only beneficial in COPD patients who are former smokers", "C. ICS should not be used in any COPD patient due to the risk of pneumonia", "D. Adding ICS to LABA therapy may improve symptoms, lung function, and quality of life in this high-risk COPD patient"]','D','ICS are indicated in COPD patients with FEV1 <60% predicted or those with asthma-COPD overlap. Adding ICS to a long-acting bronchodilator may improve symptoms, lung function, and quality of life. However, ICS use in COPD is restricted due to an increased risk of pneumonia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Inhaled Corticosteroids','hard','mcq','A child with severe persistent asthma requiring high-dose ICS for years has reduced growth velocity. Which pharmacokinetic property contributes most to this systemic effect?','["A. The fraction of ICS swallowed from the oropharynx is absorbed in the gut and enters systemic circulation", "B. ICS directly suppresses pituitary GH secretion via muscarinic receptors", "C. High-dose ICS stimulates beta-2 receptors in bone, causing growth plate suppression", "D. ICS is extensively metabolised in the lung, preventing any systemic absorption"]','A','A significant fraction of ICS is swallowed and absorbed from the GI tract, contributing to systemic exposure. With high doses and prolonged use, cumulative systemic exposure can suppress the HPA axis and reduce growth velocity in children. Using a spacer and rinsing the mouth reduces GI absorption.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Inhaled Corticosteroids','hard','mcq','Which ICS is a prodrug activated by esterases in the lung, contributing to reduced systemic bioavailability?','["A. Fluticasone", "B. Ciclesonide", "C. Beclomethasone", "D. Budesonide"]','B','Ciclesonide is an ICS prodrug activated by esterases in the lung to its active metabolite (des-ciclesonide). This pulmonary activation reduces systemic bioavailability and oropharyngeal side effects. Beclomethasone is also a prodrug (converted to beclomethasone-17-monopropionate), but budesonide and fluticasone are active drugs as inhaled.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Methylxanthines','easy','mcq','What is the primary mechanism of action of theophylline as a bronchodilator?','["A. Inhibition of 5-lipoxygenase, preventing leukotriene synthesis", "B. Selective beta-2 receptor agonism", "C. Inhibition of phosphodiesterase, increasing intracellular cAMP, plus adenosine receptor antagonism", "D. Blockade of muscarinic receptors on bronchial smooth muscle"]','C','Theophylline inhibits phosphodiesterase (PDE), preventing the breakdown of cAMP, which promotes smooth muscle relaxation. It also acts as an adenosine receptor antagonist. Both mechanisms contribute to bronchodilation. It may also have anti-inflammatory activity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Methylxanthines','easy','mcq','Which best describes the therapeutic index of theophylline?','["A. No defined therapeutic window; dose is adjusted by symptom response alone", "B. Toxic effects only occur with IV administration, not oral", "C. Wide therapeutic index with a large margin between effective and toxic doses", "D. Narrow therapeutic index requiring regular serum concentration monitoring"]','D','Theophylline has a narrow therapeutic window. Serum concentrations between 10-20 mcg/mL are typically required for bronchodilation, while levels above 20 mcg/mL cause significant toxicity. Drug interactions can elevate levels unpredictably, necessitating monitoring.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Methylxanthines','easy','mcq','Which enzyme system primarily metabolises theophylline?','["A. CYP1A2 and CYP3A4", "B. CYP2C9", "C. N-acetyltransferase 2", "D. CYP2D6"]','A','Theophylline is metabolised by CYP1A2 and CYP3A4 in the liver. Drugs that inhibit these enzymes (e.g., macrolide antibiotics like erythromycin, ciprofloxacin) reduce theophylline clearance and increase serum levels, raising toxicity risk. Inducers (e.g., rifampicin, cigarette smoking) increase clearance.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Methylxanthines','medium','mcq','A patient on theophylline for COPD is prescribed erythromycin. What is the most important clinical concern?','["A. Erythromycin accelerates theophylline metabolism, leading to sub-therapeutic levels", "B. Erythromycin inhibits CYP1A2 and CYP3A4, reducing theophylline clearance and potentially causing toxicity", "C. The combination causes fatal QT prolongation via separate mechanisms", "D. Erythromycin displaces theophylline from plasma protein binding sites"]','B','Erythromycin (and other macrolides) are potent CYP3A4 and CYP1A2 inhibitors. Co-administration with theophylline reduces its hepatic clearance, increasing serum theophylline levels into the toxic range. Theophylline dose reduction and monitoring are required.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Methylxanthines','medium','mcq','A patient on sustained-release theophylline presents with nausea, vomiting, and a seizure. Serum theophylline is 28 mcg/mL. What is the most dangerous complication?','["A. Acute kidney injury", "B. Hepatic failure", "C. Life-threatening cardiac arrhythmias and seizures", "D. Respiratory depression"]','C','Theophylline toxicity (levels >20 mcg/mL) manifests with nausea, vomiting, tremors, tachycardia, and at higher levels can cause potentially fatal cardiac arrhythmias (ventricular tachycardia/fibrillation) and seizures that are resistant to treatment. These are the most life-threatening complications of overdose.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Methylxanthines','medium','mcq','Why has theophylline largely been replaced by beta-2 agonists and ICS in modern asthma management?','["A. Theophylline is only available as an IV preparation", "B. Theophylline has no bronchodilatory activity compared to beta-2 agonists", "C. Theophylline causes fatal respiratory depression at all doses", "D. Theophylline has a narrow therapeutic window, significant drug interactions, and a poor adverse effect profile"]','D','Despite its bronchodilatory and potential anti-inflammatory effects, theophylline has been largely superseded due to its narrow therapeutic index, numerous CYP-mediated drug interactions, and adverse effects including nausea, tremors, headache, insomnia, tachycardia, seizures, and arrhythmias.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Methylxanthines','medium','mcq','A cigarette smoker taking theophylline quits smoking. What management change is required?','["A. Decrease the theophylline dose, as smoking cessation reduces CYP1A2 induction and theophylline clearance falls", "B. No change is required, as smoking does not affect theophylline metabolism", "C. Switch to IV theophylline, as oral absorption is impaired in ex-smokers", "D. Increase the theophylline dose, as nicotine induces CYP1A2"]','A','Cigarette smoking induces CYP1A2, increasing theophylline clearance. Smokers require higher theophylline doses than non-smokers. Upon quitting, CYP1A2 induction decreases over weeks, reducing theophylline clearance. If the dose is not reduced, serum levels can rise into the toxic range.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Methylxanthines','medium','mcq','What is the current role of theophylline in COPD management?','["A. First-line bronchodilator alongside ICS in all COPD patients", "B. It has largely been replaced by long-acting bronchodilators but may still have a role in selected patients with stable COPD", "C. Exclusively used for acute COPD exacerbations requiring hospitalisation", "D. Contraindicated in all COPD patients due to risk of respiratory depression"]','B','In COPD, theophylline''''s use has largely been replaced by more effective and tolerable long-acting bronchodilators (LABAs, LAMAs). However, oral theophylline can still provide benefit in selected patients with stable COPD, particularly in low-resource settings.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Methylxanthines','hard','mcq','A patient''''s theophylline level is 8 mcg/mL and asthma remains poorly controlled. What is the therapeutic serum range for theophylline?','["A. 2-5 mcg/mL", "B. 5-9 mcg/mL", "C. 10-20 mcg/mL", "D. 20-30 mcg/mL"]','C','The therapeutic serum concentration range for theophylline is 10-20 mcg/mL. Below 10 mcg/mL, bronchodilatory effects are suboptimal. Above 20 mcg/mL, toxicity (nausea, vomiting, arrhythmias, seizures) becomes likely. At 8 mcg/mL, this patient is sub-therapeutic.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Methylxanthines','hard','mcq','Which drug would INCREASE theophylline serum levels when co-administered?','["A. Phenytoin", "B. Rifampicin", "C. Carbamazepine", "D. Ciprofloxacin"]','D','Ciprofloxacin is a CYP1A2 inhibitor that reduces theophylline metabolism, raising serum levels and increasing toxicity risk. In contrast, rifampicin, carbamazepine, and phenytoin are CYP inducers that increase theophylline clearance, potentially leading to sub-therapeutic levels.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Leukotriene Modifiers','easy','mcq','What is the mechanism of action of montelukast in asthma?','["A. Selective antagonism of the cysteinyl leukotriene-1 (CysLT1) receptor", "B. Inhibition of phospholipase A2", "C. Mast cell membrane stabilisation", "D. Inhibition of 5-lipoxygenase, preventing leukotriene synthesis"]','A','Montelukast (and zafirlukast) are selective antagonists of the CysLT1 receptor. They block the effects of cysteinyl leukotrienes (LTC4, LTD4, LTE4), which cause bronchoconstriction, mucosal edema, and mucus hypersecretion. Zileuton differs — it inhibits 5-lipoxygenase, blocking all leukotriene synthesis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Leukotriene Modifiers','easy','mcq','Which leukotriene modifier works by inhibiting 5-lipoxygenase rather than blocking the receptor?','["A. Zafirlukast", "B. Zileuton", "C. Cromoglicate", "D. Montelukast"]','B','Zileuton is the only 5-lipoxygenase (5-LO) inhibitor available. By blocking 5-LO, it prevents the formation of both LTB4 (a neutrophil chemoattractant) and all cysteinyl leukotrienes. Montelukast and zafirlukast act downstream by blocking CysLT1 receptors, not synthesis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Leukotriene Modifiers','easy','mcq','In which condition are leukotriene receptor antagonists particularly useful?','["A. Pulmonary fibrosis", "B. COPD exacerbations requiring hospitalisation", "C. Aspirin-exacerbated respiratory disease (aspirin-sensitive asthma)", "D. Acute anaphylaxis"]','C','LTRAs such as montelukast are particularly effective in aspirin-exacerbated respiratory disease (AERD), where COX inhibition by NSAIDs shunts arachidonic acid metabolism towards the 5-lipoxygenase pathway, causing massive leukotriene release. LTRAs are also effective in exercise-induced bronchospasm and allergic rhinitis with asthma.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Leukotriene Modifiers','medium','mcq','A patient with persistent asthma and perennial allergic rhinitis is being considered for montelukast. What additional benefit does montelukast provide?','["A. It reduces airway colonisation with Aspergillus species", "B. It provides immediate relief of acute bronchospasm", "C. It has antibacterial properties that reduce asthma triggers", "D. It is effective for allergic rhinitis and exercise-induced bronchospasm"]','D','Montelukast is approved for prevention of exercise-induced bronchospasm and treatment of allergic rhinitis in addition to asthma. This dual efficacy is particularly useful in patients with the common combination of asthma and allergic rhinitis. It does NOT provide immediate bronchodilation for acute attacks.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Leukotriene Modifiers','medium','mcq','Which adverse effect requires monitoring during zileuton therapy?','["A. Elevation of serum hepatic enzymes", "B. Neutropenia", "C. QT interval prolongation", "D. Hyperlipidaemia"]','A','All leukotriene modifiers, including zileuton, can cause elevations in liver enzymes, requiring periodic monitoring. Zileuton also inhibits CYP1A2, which can increase theophylline levels if co-administered. Liver enzymes should be monitored and these drugs discontinued if >3-5 times the upper limit of normal.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Leukotriene Modifiers','medium','mcq','Why are leukotriene modifiers not suitable for treating an acute asthma attack?','["A. They cause bronchoconstriction when administered acutely", "B. They act slowly and are not bronchodilators; they are for prevention, not acute relief", "C. They are only available intravenously", "D. They are contraindicated in patients with reversible airflow obstruction"]','B','Leukotriene modifiers reduce the inflammatory component of asthma but do not cause acute bronchodilation. They are approved for prevention of asthma symptoms and should not be used when immediate bronchodilation is needed. SABAs remain the first-line agent for acute attacks.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Leukotriene Modifiers','medium','mcq','Food impairs the absorption of which leukotriene modifier?','["A. Montelukast", "B. Zileuton", "C. Zafirlukast", "D. All leukotriene modifiers equally"]','C','Zafirlukast''''s bioavailability is reduced by food; therefore, it should be taken at least 1 hour before or 2 hours after meals. Montelukast absorption is not significantly affected by food. This is an important counselling point for zafirlukast.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Leukotriene Modifiers','medium','mcq','A patient on zafirlukast requires anticoagulation with warfarin. What drug interaction must be considered?','["A. Zafirlukast displaces warfarin from protein-binding sites, causing bleeding", "B. No significant interaction exists between zafirlukast and warfarin", "C. Zafirlukast induces CYP2C9, reducing warfarin levels and requiring dose increase", "D. Zafirlukast inhibits CYP2C9, reducing warfarin metabolism and increasing INR"]','D','Zafirlukast inhibits CYP2C8, 2C9, and 3A4. Since S-warfarin is metabolised by CYP2C9, zafirlukast co-administration can reduce warfarin metabolism, raising plasma levels and increasing anticoagulation effect (higher INR, bleeding risk). INR should be closely monitored.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Leukotriene Modifiers','hard','mcq','A 35-year-old asthmatic develops facial droop, muscle weakness, and eosinophilia after starting montelukast. What is the most likely diagnosis?','["A. Eosinophilic granulomatosis with polyangiitis (EGPA/Churg-Strauss syndrome)", "B. Hypereosinophilic syndrome", "C. Allergic bronchopulmonary aspergillosis", "D. Drug-induced lupus"]','A','EGPA (formerly Churg-Strauss) has been reported in patients taking LTRAs, particularly montelukast. It presents with peripheral eosinophilia, vasculitis, and systemic symptoms. It is debated whether LTRAs cause EGPA or simply unmask it by allowing ICS dose reduction. Treatment requires systemic corticosteroids.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Leukotriene Modifiers','hard','mcq','Cysteinyl leukotrienes (LTC4, LTD4, LTE4) are derived from which precursor via which enzymatic pathway?','["A. From prostaglandin H2 via thromboxane synthase", "B. From arachidonic acid via the 5-lipoxygenase (5-LO) pathway", "C. From linoleic acid via cyclooxygenase-2", "D. From phosphatidylinositol via phospholipase C"]','B','Arachidonic acid (released from membrane phospholipids by phospholipase A2) is converted by 5-lipoxygenase to LTA4, which is conjugated with glutathione to form LTC4. Sequential peptide cleavage produces LTD4 and LTE4. These cysteinyl leukotrienes bind CysLT1 receptors, causing bronchoconstriction and mucus secretion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mast Cell Stabilisers and Anti-IgE','easy','mcq','What is the mechanism of action of cromolyn sodium (sodium cromoglicate) in asthma?','["A. It inhibits 5-lipoxygenase, reducing leukotriene synthesis", "B. It acts as a bronchodilator by stimulating beta-2 adrenergic receptors", "C. It inhibits mast cell degranulation and release of histamine and other mediators", "D. It blocks cysteinyl leukotriene receptors"]','C','Cromolyn (sodium cromoglicate) is a prophylactic anti-inflammatory agent that inhibits mast cell degranulation, preventing the release of histamine, leukotrienes, and other inflammatory mediators. It is not a bronchodilator and has no role in treating acute bronchospasm.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mast Cell Stabilisers and Anti-IgE','easy','mcq','Omalizumab is a monoclonal antibody used in severe persistent asthma. What is its target?','["A. Tumour necrosis factor-alpha (TNF-alpha)", "B. Interleukin-5 (IL-5)", "C. Interleukin-4 receptor alpha chain", "D. Human immunoglobulin E (IgE)"]','D','Omalizumab selectively binds to free IgE, preventing its attachment to high-affinity IgE receptors on mast cells and basophils. This reduces surface-bound IgE and limits mediator release upon allergen exposure. It is indicated for moderate-to-severe persistent allergic asthma not controlled by ICS.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mast Cell Stabilisers and Anti-IgE','easy','mcq','Why is cromolyn sodium NOT useful in the treatment of an acute asthma attack?','["A. It is not a bronchodilator and only acts prophylactically to prevent mast cell degranulation", "B. It requires 4-6 weeks of use before any benefit is seen", "C. It is contraindicated in acute asthma due to the risk of anaphylaxis", "D. It causes paradoxical bronchospasm during acute attacks"]','A','Cromolyn acts prophylactically by stabilising mast cell membranes. Once degranulation has occurred (as in an acute attack), cromolyn has no effect. Its use must begin before allergen exposure. It cannot reverse acute bronchoconstriction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mast Cell Stabilisers and Anti-IgE','medium','mcq','A patient with severe persistent allergic asthma poorly controlled despite high-dose ICS plus LABA has elevated IgE. Which biologic is most appropriate?','["A. Benralizumab", "B. Omalizumab", "C. Dupilumab", "D. Mepolizumab"]','B','Omalizumab is indicated for severe persistent allergic (IgE-mediated) asthma not controlled by ICS. It targets free IgE. Mepolizumab and benralizumab target IL-5 and are indicated for eosinophilic asthma. Dupilumab targets IL-4Ralpha and is used in eosinophilic or steroid-dependent asthma.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mast Cell Stabilisers and Anti-IgE','medium','mcq','Cromolyn sodium is prescribed for mild persistent asthma. Which dosing frequency is required?','["A. Once daily", "B. Twice daily", "C. Three to four times daily", "D. Once weekly"]','C','Cromolyn has a short duration of action and must be administered 3-4 times daily for prophylactic benefit in asthma. This frequent dosing requirement significantly impacts adherence and is a major limitation of cromolyn, limiting its use compared to ICS.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mast Cell Stabilisers and Anti-IgE','medium','mcq','Mepolizumab is a monoclonal antibody used in eosinophilic asthma. What is its mechanism?','["A. It blocks the cysteinyl leukotriene-1 receptor", "B. It inhibits phospholipase A2 in eosinophils", "C. It binds IgE, preventing mast cell degranulation", "D. It antagonises interleukin-5 (IL-5), reducing eosinophil recruitment and survival"]','D','Mepolizumab is an anti-IL-5 monoclonal antibody. IL-5 is the key cytokine for eosinophil recruitment, activation, and survival. Blocking IL-5 reduces blood and airway eosinophil counts, decreasing eosinophilic inflammation in severe persistent asthma.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mast Cell Stabilisers and Anti-IgE','medium','mcq','Which route of administration is used for omalizumab?','["A. Subcutaneous injection every 2-4 weeks", "B. Intravenous infusion monthly", "C. Oral", "D. Inhaled"]','A','Omalizumab is administered as a subcutaneous injection every 2-4 weeks, with the dose and interval determined by the patient''''s baseline IgE level and body weight. Reslizumab (another IL-5 antagonist) is given intravenously. Oral and inhaled routes are not applicable for monoclonal antibodies.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mast Cell Stabilisers and Anti-IgE','medium','mcq','Which serious adverse effect has been reported with omalizumab, requiring patient observation after each injection?','["A. Severe hypertension", "B. Anaphylaxis", "C. Pulmonary embolism", "D. Oropharyngeal candidiasis"]','B','Serious anaphylactic reactions have been reported with omalizumab, typically within 2 hours of the first injection. Patients must be observed for at least 30-60 minutes after each injection, and healthcare providers should be equipped to manage anaphylaxis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mast Cell Stabilisers and Anti-IgE','hard','mcq','How does omalizumab binding to IgE prevent allergic reactions without triggering mast cell degranulation?','["A. Omalizumab downregulates IgE synthesis by inhibiting B-cell class switching", "B. Omalizumab binds to FcepsilonRI receptors on mast cells, blocking IgE attachment", "C. Omalizumab binds to free circulating IgE at the Cepsilon3 domain (same site as FcepsilonRI), forming complexes that cannot bind mast cell receptors and thus cannot trigger degranulation", "D. Omalizumab degrades IgE via Fc-mediated phagocytosis in the spleen"]','C','Omalizumab binds to the Cepsilon3 domain of free IgE — the same region that binds FcepsilonRI on mast cells. This prevents free IgE from attaching to mast cells and basophils. Since it only binds free (not mast cell-bound) IgE, cross-linking and degranulation are avoided.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mast Cell Stabilisers and Anti-IgE','hard','mcq','How does benralizumab differ mechanistically from mepolizumab in eosinophilic asthma?','["A. Benralizumab is an oral agent; mepolizumab is subcutaneous", "B. Benralizumab targets IgE; mepolizumab targets IL-5", "C. Benralizumab binds IL-5 directly; mepolizumab binds the IL-5 receptor", "D. Benralizumab binds the IL-5 receptor alpha subunit (IL-5Ralpha), triggering NK cell-mediated eosinophil depletion via ADCC; mepolizumab binds IL-5 itself"]','D','Mepolizumab binds free IL-5, preventing it from engaging its receptor. Benralizumab binds the IL-5 receptor alpha subunit (IL-5Ralpha) on eosinophils, triggering antibody-dependent cell-mediated cytotoxicity (ADCC) via NK cells, causing rapid and near-complete eosinophil depletion.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mucolytics and Expectorants','easy','mcq','What is the mechanism by which N-acetylcysteine (NAC) acts as a mucolytic?','["A. It breaks disulfide bonds in mucus glycoproteins, reducing mucus viscosity", "B. It inhibits goblet cell secretion, reducing mucus production", "C. It activates surfactant production in type II pneumocytes", "D. It stimulates cilia in the respiratory epithelium to clear mucus"]','A','N-acetylcysteine contains a free sulfhydryl group that reduces disulfide bonds in mucus glycoproteins, fragmenting the mucus gel and reducing its viscosity. NAC is also a precursor to glutathione, giving it antioxidant properties. It is used in COPD and as an antidote for paracetamol overdose.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mucolytics and Expectorants','easy','mcq','How does guaifenesin work as an expectorant?','["A. It breaks disulfide bonds in mucus, reducing viscosity", "B. It increases the volume and reduces the viscosity of respiratory secretions, facilitating their clearance", "C. It suppresses the cough reflex centrally", "D. It stimulates beta-2 receptors in bronchial smooth muscle"]','B','Guaifenesin is an expectorant that increases the volume and hydration of bronchial secretions, thinning mucus and facilitating expectoration. Unlike mucolytics (which chemically alter mucus), guaifenesin works by increasing respiratory tract fluid production.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mucolytics and Expectorants','easy','mcq','Carbocisteine is used as a mucolytic in Ghana STG for acute bronchitis. What is its route of administration?','["A. Intranasal", "B. Inhaled via nebuliser only", "C. Oral", "D. Intravenous"]','C','Carbocisteine is available as an oral preparation (capsules and syrup). In Ghana STG 2017, it is recommended orally for adults (500-750 mg 6-8 hourly) and children (62.5-125 mg 6 hourly for ages 2-5) in acute bronchitis with productive cough.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mucolytics and Expectorants','medium','mcq','Beyond its mucolytic use, N-acetylcysteine is a first-line antidote for which life-threatening condition?','["A. Theophylline toxicity", "B. Organophosphate poisoning", "C. Methotrexate toxicity", "D. Paracetamol (acetaminophen) overdose"]','D','NAC is the standard antidote for paracetamol overdose. Paracetamol overdose depletes hepatic glutathione, allowing the toxic metabolite NAPQI to cause liver damage. NAC replenishes glutathione stores. It must be given early (within 8-24 hours) to prevent hepatic failure.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mucolytics and Expectorants','medium','mcq','A 65-year-old woman with COPD is prescribed nebulised N-acetylcysteine and develops wheeze shortly after. What is the most likely explanation?','["A. Inhalation of NAC can trigger bronchospasm, particularly in patients with reactive airway disease", "B. NAC is contraindicated in COPD and should never be used", "C. The patient has developed aspiration pneumonia from the nebulised solution", "D. NAC causes allergic bronchospasm by activating mast cells"]','A','Inhaled NAC can trigger bronchospasm in patients with reactive airway disease (including COPD and asthma) because NAC inhalation can irritate the airways. A bronchodilator (SABA) should typically be administered before nebulised NAC in susceptible patients. Oral NAC avoids this complication.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mucolytics and Expectorants','medium','mcq','What is the key difference between an expectorant and a mucolytic?','["A. Expectorants suppress cough; mucolytics stimulate cough", "B. Expectorants increase respiratory secretions to aid clearance; mucolytics chemically break down the mucus structure", "C. Expectorants are inhaled; mucolytics are given orally", "D. Expectorants are only used in children; mucolytics are for adults only"]','B','Expectorants (e.g., guaifenesin) increase hydration and volume of respiratory secretions, facilitating their removal by cough and ciliary action. Mucolytics (e.g., NAC, carbocisteine) chemically reduce mucus viscosity by breaking glycoprotein bonds. Both approaches aim to improve sputum clearance but through different mechanisms.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mucolytics and Expectorants','medium','mcq','In which condition is nebulised NAC indicated as a mucolytic to facilitate airway clearance?','["A. Pulmonary hypertension with right heart failure", "B. Acute asthma exacerbation", "C. Cystic fibrosis and viscous mucus plugging in COPD", "D. Allergic rhinitis with post-nasal drip"]','C','Nebulised NAC is used to thin viscous mucus secretions in conditions such as cystic fibrosis, bronchiectasis, and COPD where thick secretions obstruct airways. In cystic fibrosis, dornase alfa (recombinant DNase) is now preferred as excess DNA from neutrophil breakdown also contributes to mucus viscosity.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mucolytics and Expectorants','medium','mcq','Which is a correct statement about guaifenesin?','["A. Guaifenesin should be avoided in patients with productive cough", "B. Guaifenesin requires a prescription due to its high abuse potential", "C. Guaifenesin is effective as an antitussive (cough suppressant)", "D. Guaifenesin is an expectorant that facilitates mucus removal but does not suppress cough"]','D','Guaifenesin is an expectorant, not an antitussive. It thins secretions to aid expectoration but does not suppress the cough reflex. It is often combined with codeine or dextromethorphan in OTC products, where the latter components provide the antitussive effect.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mucolytics and Expectorants','hard','mcq','A patient with IPF asks about pirfenidone. How does pirfenidone differ from traditional mucolytics?','["A. Pirfenidone is an antifibrotic agent that inhibits TGF-beta signalling, collagen synthesis, and fibroblast proliferation \u2014 unrelated to mucus clearance", "B. Pirfenidone is a phosphodiesterase inhibitor that reduces fibrotic airway remodelling", "C. Pirfenidone is a leukotriene receptor antagonist that prevents fibrosis in atopic patients", "D. Pirfenidone is a mucolytic that breaks disulfide bonds in fibrotic connective tissue"]','A','Pirfenidone is an antifibrotic drug approved for IPF. Its mechanisms include inhibition of TGF-beta-mediated fibroblast proliferation, collagen synthesis, and profibrotic cytokine production. It is fundamentally different from mucolytics, which address mucus properties.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Mucolytics and Expectorants','hard','mcq','Dornase alfa (recombinant human DNase I) is used in cystic fibrosis. What is its specific substrate in CF sputum?','["A. Sulphated mucin glycoproteins", "B. Extracellular DNA released from neutrophils, which increases sputum viscosity in cystic fibrosis", "C. Arachidonic acid trapped in mucus", "D. Disulfide-bridged mucus glycoproteins"]','B','In CF, massive neutrophil recruitment releases extracellular DNA into the airways, dramatically increasing sputum viscosity. Dornase alfa cleaves this extracellular DNA, reducing sputum viscosity and improving mucociliary clearance. This is distinct from NAC (which breaks disulfide bonds in mucins) and carbocisteine.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Antitussives','easy','mcq','How does codeine suppress cough?','["A. It stimulates mu-opioid receptors in the peripheral airways", "B. It anesthetises stretch receptors in the respiratory passages peripherally", "C. It decreases the sensitivity of cough centres in the CNS to peripheral stimuli and decreases mucosal secretion", "D. It blocks histamine H1 receptors in the medulla"]','C','Codeine acts centrally as an opioid to reduce the sensitivity of the cough centre in the medulla oblongata to peripheral stimuli. It also decreases mucosal secretion. Antitussive effects occur at doses lower than analgesic doses. Codeine has addictive potential and causes constipation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Antitussives','easy','mcq','Which antitussive suppresses cough through a peripheral mechanism by anesthetising stretch receptors in the airways?','["A. Guaifenesin", "B. Codeine", "C. Dextromethorphan", "D. Benzonatate"]','D','Benzonatate (a non-opioid antitussive) suppresses cough by peripheral action: it anesthetises stretch receptors in the respiratory passages, lungs, and pleura, reducing the afferent limb of the cough reflex. Unlike opioids, it has no central mechanism and no analgesic or abuse potential.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Antitussives','easy','mcq','Which patient should NOT receive codeine-based antitussives?','["A. A patient with a history of opioid use disorder presenting with viral cough", "B. An adult patient with chronic asthma requiring bronchodilator therapy", "C. A patient with mild allergic rhinitis-associated cough", "D. A 50-year-old woman with productive cough due to COPD exacerbation"]','A','Codeine is an opioid with significant addictive potential. In patients with a history of opioid addiction, codeine should be avoided as it can trigger relapse. Dextromethorphan (with low abuse potential at antitussive doses) or benzonatate are safer alternatives.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Antitussives','medium','mcq','How does dextromethorphan differ from codeine?','["A. Dextromethorphan has stronger analgesic properties than codeine", "B. Dextromethorphan is a synthetic opioid derivative with no analgesic effect at antitussive doses and a better safety profile", "C. Dextromethorphan acts peripherally, while codeine acts centrally", "D. Dextromethorphan is more addictive than codeine at standard doses"]','B','Dextromethorphan is a synthetic morphine derivative that has antitussive efficacy equal to codeine but without analgesic activity at recommended doses. It has a lower risk of dependence at therapeutic doses but can be abused at high doses. Codeine has greater analgesic and dependence potential.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Antitussives','medium','mcq','A patient with productive cough due to lower respiratory tract infection asks for a cough suppressant. What is the key clinical consideration?','["A. All antitussives are equally safe regardless of the aetiology of cough", "B. Antitussives should always be prescribed for any cough to improve patient comfort", "C. Cough is a defence mechanism; suppression may be inappropriate when cough is productive and helping clear infection; treat the underlying cause first", "D. Antitussives are only indicated for dry cough in children under 12"]','C','Cough is an important defence reflex that helps clear secretions and pathogens. Suppressing a productive cough can impair clearance of infection. Guidelines recommend identifying the underlying cause before prescribing antitussives. Expectorants or mucolytics may be more appropriate for productive cough.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Antitussives','medium','mcq','Which drug is recommended by Ghana STG 2017 for dry non-productive cough in acute bronchitis in children aged 7-12 years?','["A. Benzonatate 100 mg three times daily", "B. Guaifenesin/carbocisteine combination twice daily", "C. Codeine 10-20 mg 6-8 hourly", "D. Dextromethorphan 15 mg 6-8 hourly (max 60 mg/day)"]','D','Ghana STG 2017 recommends dextromethorphan-containing preparations for dry/non-productive cough in acute bronchitis: children aged 7-12 years receive 15 mg every 6-8 hours (maximum 60 mg/day). Children under 4 years should not receive dextromethorphan.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Antitussives','medium','mcq','Which adverse effect is specifically associated with benzonatate if the capsules are bitten or chewed?','["A. Severe oropharyngeal numbness from direct contact with mucosa", "B. Bronchospasm from rapid systemic absorption", "C. Severe hypertension from alpha-1 receptor stimulation", "D. Hepatotoxicity from early intestinal absorption"]','A','Benzonatate capsules must be swallowed intact. If bitten or chewed, the drug makes direct contact with the oral mucosa, causing intense numbness and tingling of the mouth and throat. This can lead to choking, laryngospasm, or cardiovascular effects.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Antitussives','medium','mcq','ACE inhibitor-induced cough requires which management approach?','["A. Prescribe codeine for long-term cough suppression", "B. Switch the patient from an ACE inhibitor to an angiotensin receptor blocker (ARB)", "C. Add dextromethorphan to the ACE inhibitor regimen", "D. Prescribe inhaled ipratropium for ACE inhibitor cough"]','B','ACE inhibitor-induced cough occurs in 10-15% of patients due to accumulation of bradykinin and substance P in the airways. The appropriate management is to switch to an ARB (e.g., losartan), which does not inhibit bradykinin degradation. Antitussives are not the appropriate approach.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Antitussives','hard','mcq','Dextromethorphan at high doses causes a dissociative psychedelic syndrome. What receptor does it act upon at supratherapeutic doses?','["A. Kappa-opioid receptor agonism", "B. Mu-opioid receptor", "C. N-methyl-D-aspartate (NMDA) receptor antagonism", "D. Serotonin 5-HT2A receptor agonism"]','C','At antitussive doses, dextromethorphan acts via sigma receptors. At high/supratherapeutic doses (abuse doses), it acts as an NMDA receptor antagonist (similar to ketamine), producing dissociative, hallucinogenic effects. It also has some serotonin reuptake inhibition, which can cause serotonin syndrome when combined with MAO inhibitors.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Antitussives','hard','mcq','A patient taking phenelzine (a MAO inhibitor) develops hyperthermia, agitation, clonus, and diaphoresis after taking a cold remedy containing dextromethorphan. What syndrome has occurred?','["A. Anticholinergic toxidrome", "B. Opioid toxidrome", "C. Neuroleptic malignant syndrome", "D. Serotonin syndrome"]','D','Dextromethorphan inhibits serotonin reuptake and is a sigma receptor agonist. Combined with MAO inhibitors (which prevent serotonin breakdown), this dramatically increases synaptic serotonin, causing serotonin syndrome: hyperthermia, agitation, clonus, diaphoresis, tremor, and potentially fatal autonomic instability. Dextromethorphan is contraindicated with MAO inhibitors.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Pulmonary Hypertension Drugs','easy','mcq','Sildenafil is used in pulmonary arterial hypertension (PAH). What is its mechanism?','["A. Inhibition of phosphodiesterase-5 (PDE5), increasing cyclic GMP and causing pulmonary vasodilation", "B. Prostacyclin receptor agonism, promoting pulmonary vasodilation", "C. Beta-2 receptor stimulation in pulmonary vascular smooth muscle", "D. Endothelin receptor blockade, reducing pulmonary vasoconstriction"]','A','Sildenafil is a selective PDE5 inhibitor. PDE5 degrades cGMP in vascular smooth muscle; inhibiting it increases cGMP, enhancing nitric oxide (NO)-mediated vasodilation. In the lungs, this selectively reduces pulmonary vascular resistance. Tadalafil is another PDE5 inhibitor used in PAH.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Pulmonary Hypertension Drugs','easy','mcq','Bosentan is used for PAH. What is its pharmacological class?','["A. Prostacyclin analogue", "B. Dual endothelin receptor antagonist (ERA)", "C. Soluble guanylate cyclase stimulator", "D. PDE5 inhibitor"]','B','Bosentan is a dual endothelin receptor antagonist (blocks both ETA and ETB receptors). Endothelin-1 is a potent vasoconstrictor and proliferative factor. Blocking its receptors reduces pulmonary vasoconstriction and vascular remodelling. Macitentan and ambrisentan are other ERAs used in PAH.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Pulmonary Hypertension Drugs','easy','mcq','Epoprostenol (prostacyclin) is used in severe PAH. How is it administered?','["A. Oral daily", "B. Inhaled twice daily", "C. Continuous IV infusion via central venous catheter", "D. Subcutaneous injection weekly"]','C','Epoprostenol has an extremely short half-life (3-5 minutes) and must be administered as a continuous IV infusion through a central venous catheter. Abrupt interruption can cause fatal rebound pulmonary hypertension. Inhaled iloprost (a prostacyclin analogue) is an alternative with a more convenient route.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Pulmonary Hypertension Drugs','medium','mcq','A woman of childbearing age is prescribed bosentan for PAH. What is a critical counselling point?','["A. She must avoid sunlight due to photosensitivity from bosentan", "B. Bosentan should be taken at bedtime to avoid daytime hypotension", "C. She should take bosentan with food to prevent hepatotoxicity", "D. Bosentan is teratogenic and requires mandatory pregnancy prevention; it also reduces the efficacy of oral contraceptives"]','D','Bosentan is highly teratogenic. Additionally, bosentan induces CYP3A4 and CYP2C9, reducing plasma levels of hormonal contraceptives. Women of childbearing age must use two reliable forms of contraception. Monthly pregnancy tests and liver function monitoring are required.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Pulmonary Hypertension Drugs','medium','mcq','What is the mechanism by which epoprostenol reduces pulmonary vascular resistance?','["A. It binds prostacyclin (IP) receptors, stimulating adenylyl cyclase, increasing cAMP, and causing vasodilation and inhibition of platelet aggregation", "B. It inhibits angiotensin-converting enzyme in the pulmonary vasculature", "C. It blocks L-type calcium channels in pulmonary vascular smooth muscle", "D. It acts as a thromboxane A2 receptor antagonist"]','A','Epoprostenol (prostacyclin, PGI2) binds IP receptors coupled to Gs proteins, stimulating adenylyl cyclase and increasing intracellular cAMP. This causes vasodilation of pulmonary (and systemic) vascular smooth muscle and inhibits platelet aggregation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Pulmonary Hypertension Drugs','medium','mcq','Riociguat is used in PAH. What is its mechanism?','["A. It inhibits PDE5, preventing cGMP degradation", "B. It directly stimulates soluble guanylate cyclase (sGC), increasing cGMP and causing pulmonary vasodilation", "C. It blocks endothelin ETA receptors selectively", "D. It is a prostacyclin receptor agonist"]','B','Riociguat is a soluble guanylate cyclase (sGC) stimulator. It directly stimulates sGC (increasing cGMP synthesis) and sensitises sGC to nitric oxide. Unlike sildenafil (which prevents cGMP breakdown), riociguat increases cGMP production. It is contraindicated with PDE5 inhibitors due to risk of severe hypotension.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Pulmonary Hypertension Drugs','medium','mcq','A PAH patient on continuous epoprostenol infusion has his IV line disconnected for 2 hours. What is the most dangerous consequence?','["A. Hypoglycaemia from metabolic effects", "B. Acute liver failure from drug accumulation", "C. Rebound severe pulmonary hypertension and right heart failure", "D. Systemic hypertensive crisis"]','C','Abrupt discontinuation of epoprostenol infusion can cause life-threatening rebound pulmonary hypertension due to sudden loss of vasodilation. This can precipitate acute right heart failure and death. Patients must carry emergency back-up infusion supplies.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Pulmonary Hypertension Drugs','medium','mcq','Which drug for pulmonary hypertension is contraindicated in combination with nitrates due to risk of severe hypotension?','["A. Epoprostenol", "B. Ambrisentan", "C. Bosentan", "D. Sildenafil"]','D','Sildenafil and other PDE5 inhibitors are absolutely contraindicated with nitrates (e.g., GTN, isosorbide mononitrate). Both drugs increase cGMP-mediated vasodilation; the combination causes profound, potentially fatal hypotension.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Pulmonary Hypertension Drugs','hard','mcq','Selexipag is an oral agent for PAH. How does it differ mechanistically from epoprostenol?','["A. Selexipag is a selective IP receptor agonist that is non-prostanoid in structure, providing oral bioavailability and a longer half-life than epoprostenol", "B. Selexipag is a PDE5 inhibitor with additional anti-inflammatory properties", "C. Selexipag blocks thromboxane A2 synthesis, reducing platelet-driven vasoconstriction", "D. Selexipag is a dual endothelin and prostacyclin receptor antagonist"]','A','Selexipag is an oral, non-prostanoid selective IP (prostacyclin) receptor agonist. Unlike epoprostenol (a natural prostacyclin with a 3-5 minute half-life requiring IV infusion), selexipag and its active metabolite have longer half-lives and oral bioavailability, mimicking the vasodilatory effects of prostacyclin without the infusion logistics.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Pulmonary Hypertension Drugs','hard','mcq','A PAH patient receives both sildenafil and bosentan. Bosentan reduces sildenafil plasma levels. What is the mechanism?','["A. Bosentan inhibits CYP3A4, reducing sildenafil metabolism", "B. Bosentan induces CYP3A4 and CYP2C9, increasing sildenafil metabolism and reducing its plasma levels", "C. Bosentan competes with sildenafil for PDE5 binding", "D. Bosentan increases renal clearance of sildenafil via P-glycoprotein"]','B','Bosentan is a potent inducer of CYP3A4 and CYP2C9. Sildenafil is primarily metabolised by CYP3A4. Co-administration of bosentan accelerates sildenafil metabolism, significantly reducing its plasma levels (by up to 63%) and potentially diminishing its therapeutic effect.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Respiratory Drug Interactions and Adverse Effects','easy','mcq','Which drug class is contraindicated in patients with asthma due to risk of life-threatening bronchospasm?','["A. Loop diuretics", "B. ACE inhibitors", "C. Non-selective beta-blockers (e.g., propranolol)", "D. Calcium channel blockers"]','C','Non-selective beta-blockers (e.g., propranolol, timolol) block beta-2 receptors on bronchial smooth muscle, preventing physiological bronchodilation. In asthmatic patients, this can precipitate severe, potentially fatal bronchospasm. Even topical ophthalmic beta-blocker drops can cause sufficient systemic absorption to trigger this.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Respiratory Drug Interactions and Adverse Effects','easy','mcq','What is the most important instruction for a patient starting ICS to prevent oral candidiasis?','["A. Always use a nebuliser rather than an MDI", "B. Breathe through the nose during inhaler use", "C. Take an antifungal prophylactically with every ICS dose", "D. Rinse the mouth with water in a swish-and-spit method after each inhaler use"]','D','Oropharyngeal candidiasis is caused by local immune suppression from ICS deposition in the mouth and pharynx. Rinsing the mouth with water (swish-and-spit) after each ICS use removes drug from the mucosal surfaces. Using a spacer device also reduces oropharyngeal deposition significantly.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Respiratory Drug Interactions and Adverse Effects','easy','mcq','A patient on theophylline is started on clarithromycin. What monitoring is most important?','["A. Theophylline serum levels and signs of toxicity (nausea, arrhythmia, seizures)", "B. Peak expiratory flow rate daily", "C. Liver function tests weekly", "D. Serum potassium every 48 hours"]','A','Clarithromycin (a macrolide) inhibits CYP3A4, reducing theophylline metabolism and raising serum levels. Theophylline toxicity (nausea, tremors, cardiac arrhythmias, seizures) can occur rapidly. Theophylline serum levels should be measured, and the dose reduced if levels approach or exceed 20 mcg/mL.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Respiratory Drug Interactions and Adverse Effects','medium','mcq','NSAIDs trigger asthma attacks in aspirin-exacerbated respiratory disease (AERD). What is the pharmacological mechanism?','["A. NSAIDs activate IgE-mediated mast cell degranulation", "B. COX inhibition by NSAIDs diverts arachidonic acid to the 5-lipoxygenase pathway, causing massive leukotriene release and bronchoconstriction", "C. NSAIDs stimulate beta-1 adrenergic receptors, causing reflex bronchospasm", "D. NSAIDs inhibit surfactant production, causing airway collapse"]','B','In AERD (affecting approximately 10% of asthmatics), COX-1 inhibition by NSAIDs prevents prostaglandin E2 synthesis, which normally inhibits 5-lipoxygenase. This disinhibition causes a marked increase in cysteinyl leukotriene production, triggering bronchoconstriction. LTRAs and zileuton are particularly useful in this condition.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Respiratory Drug Interactions and Adverse Effects','medium','mcq','Long-term high-dose systemic corticosteroids for asthma can cause which of the following systemic adverse effects?','["A. Nephrotic syndrome and glomerulosclerosis", "B. Hyperkalemia and hypertension from mineralocorticoid excess", "C. Osteoporosis, HPA suppression, hyperglycaemia, and growth retardation in children", "D. Pulmonary hypertension and right heart failure"]','C','Chronic systemic corticosteroid use causes numerous serious adverse effects: osteoporosis, HPA axis suppression (adrenal insufficiency on withdrawal), hyperglycaemia/diabetes, weight gain, cataracts, growth retardation in children, and increased infection susceptibility. ICS minimise these risks at standard doses.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Respiratory Drug Interactions and Adverse Effects','medium','mcq','A 70-year-old man with asthma develops acute urinary retention after being prescribed an inhaled anticholinergic bronchodilator. Which pre-existing condition most predisposed him?','["A. Atrial fibrillation", "B. Type 2 diabetes mellitus", "C. Chronic kidney disease", "D. Benign prostatic hyperplasia (BPH)"]','D','Anticholinergic agents (ipratropium, tiotropium) reduce detrusor muscle contraction via muscarinic receptor blockade. In patients with BPH, where bladder outflow is already compromised, even low systemic absorption from inhaled anticholinergics can precipitate acute urinary retention.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Respiratory Drug Interactions and Adverse Effects','medium','mcq','Which drug combination poses the greatest risk of serious drug interaction in a patient with asthma?','["A. Theophylline + ciprofloxacin", "B. Ipratropium + salbutamol", "C. Inhaled budesonide + salbutamol", "D. Montelukast + cetirizine"]','A','Ciprofloxacin inhibits CYP1A2, markedly reducing theophylline clearance. This can cause serum theophylline levels to rise into the toxic range (>20 mcg/mL), resulting in nausea, arrhythmias, and seizures. This is a potentially life-threatening interaction. Theophylline dose reduction and serum level monitoring are mandatory.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Respiratory Drug Interactions and Adverse Effects','medium','mcq','A patient with COPD on long-term ICS develops Streptococcus pneumoniae pneumonia. Which drug therapy may have contributed?','["A. Long-acting beta-2 agonists, which suppress mucociliary clearance", "B. Inhaled corticosteroids, which increase pneumonia risk in COPD patients", "C. Tiotropium, which reduces surfactant production", "D. Theophylline, which impairs macrophage function"]','B','In COPD patients, ICS use is associated with an increased risk of pneumonia, likely due to local immunosuppression impairing pulmonary defences against bacteria. This is a key reason why ICS use in COPD is restricted to patients with FEV1 <60% or asthma-COPD overlap.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Respiratory Drug Interactions and Adverse Effects','hard','mcq','A patient with asthma who uses high-dose ICS for many years undergoes surgery and postoperatively develops hypotension refractory to fluid resuscitation. What is the most likely underlying pharmacological cause?','["A. Pulmonary embolism from ICS-induced hypercoagulability", "B. Hyponatraemia from mineralocorticoid excess", "C. Adrenal crisis due to HPA axis suppression from chronic high-dose ICS", "D. Severe anaphylaxis to the anaesthetic agent"]','C','High-dose ICS, particularly with systemic absorption over many years, can suppress the hypothalamic-pituitary-adrenal (HPA) axis. In the perioperative period (a time of stress), the suppressed adrenal glands cannot mount an adequate cortisol response, leading to adrenal crisis: refractory hypotension, hyponatraemia, and hypoglycaemia. Perioperative stress-dose corticosteroid cover should be considered.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Respiratory System','Pharmacology','Respiratory Drug Interactions and Adverse Effects','hard','mcq','Zileuton inhibits CYP1A2 and is co-prescribed with theophylline. What specific adverse effect is most likely to occur?','["A. Zileuton competes with theophylline at the same adenosine receptors, causing antagonism", "B. Zileuton displaces theophylline from albumin binding, transiently elevating free drug levels", "C. Theophylline levels decrease due to CYP induction, causing sub-therapeutic bronchodilation", "D. Theophylline levels increase due to CYP1A2 inhibition by zileuton, risking nausea, arrhythmias, and seizures"]','D','Zileuton inhibits CYP1A2, one of the key enzymes responsible for theophylline metabolism. Co-administration reduces theophylline clearance, raising serum levels towards the toxic range. Given theophylline''''s narrow therapeutic index, this interaction is clinically significant. Theophylline dose should be halved and serum levels monitored when zileuton is added.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');